import { Nav, Navbar, NavDropdown } from "react-bootstrap";
import Logo from "./four.png";
import './Home.css';
import 'bootstrap/dist/css/bootstrap.min.css';


function Home() {
  return (

    <Navbar collapseOnSelect expand="lg"  variant="dark">
      <Navbar.Brand href="#home">
        <font id='heading1'><img src={Logo} className='church-logo'/>Foursquare</font>
      </Navbar.Brand>
      <div className="'avlink1">
        <Nav> 
          <Nav.Link href="#" id=''>HOME</Nav.Link>
          <Nav.Link href="#" id=''>ABOUT</Nav.Link>
          <Nav.Link href="#" id='' >SERVE</Nav.Link>
          <Nav.Link href="#" id='' >MEDIA</Nav.Link>
          <Nav.Link href="#" id='' >CONTANT US</Nav.Link>
        </Nav>
        </div>
      </Navbar>

  );
}
export default Home;
